// Timeline — everything the apex knows about it: origin, gateway allowlist, route, Apps-section
// entry (web-app-suite.md F4). Generated by scripts/new-web-app.sh; adding this file IS the
// registration (`registry/index.ts` globs `apps/*.ts`).
import type { ProxyMethodAllowlist } from '@tenshu/sdk/bridge'
import { appOrigin, SESSION_METHODS, type AppGlance, type HostedApp } from '../types'
import { browserZone, civilDate, localDateTime } from '../glanceTime'

declare global {
  interface ImportMetaEnv {
    /** The Timeline app's origin (see `apps/registry/apps/timeline.ts`). */
    readonly VITE_TIMELINE_ORIGIN?: string
  }
}

// ⚠⚠ F5 — exactly the methods `web/timeline` calls: its `ProxyMethod` table in
// `web/timeline/src/lib/proxy.ts` (`gatewayPermissions.test.ts` fails on drift either way). Exact
// names only; a `.*` prefix only for a namespace this app owns outright, and never a bare `'*'`.
// ⚠ Not granted, on purpose: the raw `timeline.moments` / `.moment` / `.trips` / `.traces` reads
// (the projected surface supersedes them), `timeline.movementRoute` (no leg boundaries — the maps
// read every leg in one `movementRoutes`), and of `mapRegion.*` only the map's two reads — no
// `mapRegion.regionsIn` / `.catalog`, which no Timeline map calls. Nothing of another app's: no
// `fs.*`, no `contact.*`, no `calendar.*`.
const METHODS: ProxyMethodAllowlist = [
  ...SESSION_METHODS,
  'timeline.feed',
  'timeline.feed.observe',
  'timeline.momentDetail',
  'timeline.trip',
  'timeline.places',
  'timeline.places.observe',
  'timeline.place',
  'timeline.renamePlace',
  'timeline.setPlaceRole',
  'timeline.mergePlaces',
  'timeline.unmergePlace',
  'timeline.acceptTripSuggestion',
  'timeline.dismissTripSuggestion',
  // The trip, movement and place maps (web-app-suite.md Wave 3, Timeline routes).
  'timeline.movementRoutes',
  'mapRegion.regionAt',
  'mapRegion.streamRange',
]

const PROD_ORIGIN = 'https://timeline.tenshu.app'

// The overview card (web-apex-home.md §3.6): today's latest places and trips.
// ⚠ Cost: there is no day-scoped read on the web, so this is the whole `timeline.feed` — the same
// read the Timeline app makes on open — keeping today only. A day-scoped op is the fix if it shows.
const TODAY_ROWS = 3
const glance: AppGlance = {
  size: 'narrow',
  subtitle: 'today',
  async load(call) {
    const result = (await call('timeline.feed', { zone: browserZone() })) as FeedResult
    if (!result.ok) throw new Error(result.error.kind)
    const today = civilDate(new Date())
    const moments = result.days.find(d => d.date === today)?.moments ?? []
    const rows = [...moments]
      .sort((a, b) => b.timestampMs - a.timestampMs)
      .slice(0, TODAY_ROWS)
      .map(m => ({ ...wording(m), startLocal: localDateTime(m.timestampMs), allDay: false, detail: m.placeCity ?? '' }))
    return { layout: 'agenda', rows }
  },
}

// ⚠ The stored `title` is composed at ingest, in English; the Timeline app never shows it
// (`web/timeline/src/lib/format.ts` momentTitle) and neither does this card. A place's NAME is user
// data and goes as the title; everything else is a catalogue key the apex words.
const MOVEMENT_MODES = ['walk', 'run', 'cycle', 'drive', 'transit', 'flight'] as const
const ACTIVITY_TYPES = ['running', 'walking', 'cycling', 'strength'] as const
type FeedMoment = Extract<FeedResult, { ok: true }>['days'][number]['moments'][number]
function wording(m: FeedMoment): { title: string; titleKey: string } {
  switch (m.kind) {
    case 'Visit':
      if (m.placeRole === 'home' || m.placeRole === 'work') return { title: '', titleKey: `placeRole.${m.placeRole}` }
      return m.placeName ? { title: m.placeName, titleKey: '' } : { title: '', titleKey: 'moment.place' }
    case 'Movement':
      return {
        title: '',
        titleKey: (MOVEMENT_MODES as readonly string[]).includes(m.movementMode ?? '')
          ? `movement.${m.movementMode}`
          : 'movement.unknown',
      }
    case 'Activity': {
      const key = (m.activityType ?? '').toLowerCase()
      return { title: '', titleKey: (ACTIVITY_TYPES as readonly string[]).includes(key) ? `activity.${key}` : 'activity.other' }
    }
    default:
      return { title: '', titleKey: 'moment.other' }
  }
}

type FeedResult =
  | {
      readonly ok: true
      readonly days: readonly {
        readonly date: string
        readonly moments: readonly {
          readonly timestampMs: number
          readonly kind: string
          readonly placeName: string | null
          readonly placeCity: string | null
          readonly placeRole: string | null
          readonly movementMode: string | null
          readonly activityType: string | null
        }[]
      }[]
    }
  | { readonly ok: false; readonly error: { readonly kind: string } }

export const timeline: HostedApp = {
  id: 'timeline',
  order: 30,
  title: 'Timeline',
  prodOrigin: PROD_ORIGIN,
  envName: 'VITE_TIMELINE_ORIGIN',
  devPort: 5177,
  origin: () => appOrigin(import.meta.env.VITE_TIMELINE_ORIGIN, PROD_ORIGIN, 5177),
  methods: METHODS,
  routePath: 'timeline/*',
  sections: ['', 'places'],
  glance,
  // ⚠ DISPLAY data for the Apps section — what the app can actually call is `methods` above.
  manifest: {
    id: 'timeline',
    label: 'Timeline',
    description: 'Where you have been, end-to-end encrypted.',
    version: '0.1.0',
    launchPath: '/timeline',
    // ⚠ The permissions listed here are DISPLAY data — what the app can actually call is `methods`.
    permissions: [
      {
        id: 'timeline.read',
        label: 'Read your timeline',
        description: 'See your visits, movements, trips and places.',
        state: 'granted',
        lastUsedAtMs: null,
      },
      {
        id: 'timeline.write',
        label: 'Edit your places and trips',
        description: 'Rename and label places, merge or separate them, and save suggested trips.',
        state: 'granted',
        lastUsedAtMs: null,
      },
    ],
    services: [
      {
        id: 'timeline',
        label: 'TimelineService',
        reason: 'Stores your moments and trips, encrypted client-side.',
      },
      {
        id: 'place',
        label: 'PlaceService',
        reason: 'Stores your places, their names and labels.',
      },
      {
        id: 'health',
        label: 'HealthService',
        reason: 'Names the activity behind a workout moment. Read only.',
      },
    ],
  },
}

export default timeline
